/**
 * GET /api/tts?text=...&locale=...
 *
 * Teach-aloud audio for a practice word or sentence, generated by the speech
 * service (services/speech, neural voices). Browsers often have no voice for
 * Indian languages, so the practice page plays this first and only falls back
 * to the browser's own voices if it fails.
 */

import { NextResponse } from 'next/server';
import { createClient } from '@/lib/supabase/server';
import { speechServiceEnv } from '@/lib/env.server';
import { isLanguageEnabled } from '@/lib/languages';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

const MAX_TEXT_CHARS = 200;

function fail(status: number, code: string, message: string) {
  return NextResponse.json({ error: { code, message } }, { status });
}

export async function GET(request: Request) {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return fail(401, 'unauthenticated', 'Please sign in.');

  const params = new URL(request.url).searchParams;
  const text = params.get('text')?.trim() ?? '';
  const locale = params.get('locale') ?? '';

  if (!text || text.length > MAX_TEXT_CHARS) {
    return fail(400, 'bad_request', 'Text must be 1-200 characters.');
  }
  if (!isLanguageEnabled(locale)) {
    return fail(400, 'locale_unsupported', 'That language is not enabled.');
  }

  const { url, token } = speechServiceEnv();
  const upstream = new URL(`${url}/tts`);
  upstream.searchParams.set('text', text);
  upstream.searchParams.set('locale', locale);
  upstream.searchParams.set('slow', params.get('slow') === 'false' ? 'false' : 'true');

  let response: Response;
  try {
    response = await fetch(upstream, {
      headers: token ? { Authorization: `Bearer ${token}` } : undefined,
      cache: 'no-store',
      signal: AbortSignal.timeout(15_000),
    });
  } catch (error) {
    console.error(`[tts] could not reach the speech service at ${url}`, error);
    return fail(503, 'provider_unavailable', 'The teaching voice is unavailable right now.');
  }

  if (!response.ok) {
    return fail(503, 'provider_unavailable', 'The teaching voice is unavailable right now.');
  }

  return new NextResponse(await response.arrayBuffer(), {
    headers: {
      'Content-Type': 'audio/mpeg',
      // Same text + locale always gives the same audio; let the browser reuse it.
      'Cache-Control': 'private, max-age=86400',
    },
  });
}
